// PayPal client - SANDBOX ONLY. Built on PayPal's official TypeScript Server
// SDK (@paypal/paypal-server-sdk, generated by APIMatic), integrated with the
// help of APIMatic's Context Plugin for PayPal Server SDKs. The environment is
// fixed to Sandbox; there is no way to point this at live PayPal from
// configuration. Credentials come from the environment and are never logged.

import "server-only";
import { ApiError, Client, Environment, type OAuthToken } from "@paypal/paypal-server-sdk";

const MAYBE_DONE = new Set(["DUPLICATE_TRANSACTION", "DUPLICATE_INVOICE_ID", "DUPLICATE_REQUEST_ID"]);

export class PayPalError extends Error {
  constructor(
    message: string,
    // 0 = no response (timeout, network, or no token): the outcome at PayPal is unknown.
    readonly status: number,
    readonly issue: string | null,
    readonly debugId: string | null,
  ) {
    super(message);
    this.name = "PayPalError";
  }

  // A definite refusal: PayPal answered 4xx (other than rate limiting), so
  // nothing happened and it is safe to release what we reserved. A "duplicate"
  // answer is the opposite - the money may already have moved - so it never counts.
  get definite(): boolean {
    return this.status >= 400 && this.status < 500 && this.status !== 429 && !MAYBE_DONE.has(this.issue ?? "");
  }
}

function env(name: string): string {
  const v = process.env[name];
  if (!v) throw new Error(`${name} is not set`);
  return v;
}

// One long-lived client for the process: it caches the OAuth token.
let client: Client | null = null;
export function paypalClient(): Client {
  client ??= new Client({
    environment: Environment.Sandbox,
    // The SDK's default is no timeout at all; never wait on PayPal forever.
    timeout: 20_000,
    // Retries stay off (the SDK default, and it never retries POST anyway): a
    // capture is retried by our own code with the same PayPal-Request-Id.
    clientCredentialsAuthCredentials: {
      oAuthClientId: env("PAYPAL_CLIENT_ID"),
      oAuthClientSecret: env("PAYPAL_CLIENT_SECRET"),
      oAuthClockSkew: 60,
      // The SDK keeps one shared token promise per client, so a provider that
      // rejects once (say, a network blip while fetching the token) would break
      // every later call. Always resolve: on failure hand back an expired
      // token, which fails just this call and is fetched again next time.
      oAuthTokenProvider: async (last, manager): Promise<OAuthToken> => {
        try {
          return await manager.fetchToken();
        } catch (e) {
          console.error("[paypal] could not get an access token", e instanceof ApiError ? `HTTP ${e.statusCode}` : e instanceof Error ? e.name : "error");
          return { ...(last ?? { accessToken: "", tokenType: "Bearer" }), expiry: BigInt(0) };
        }
      },
    },
  });
  return client;
}

// Unsigned JWT telling PayPal which merchant the platform acts for.
export function authAssertion(merchantId: string): string {
  const b64 = (o: object) => Buffer.from(JSON.stringify(o)).toString("base64url");
  return `${b64({ alg: "none" })}.${b64({ iss: env("PAYPAL_CLIENT_ID"), payer_id: merchantId })}.`;
}

// Runs one SDK call and turns failures into PayPalError: an HTTP error from
// PayPal keeps its status (definite or not), anything else - timeout, network,
// no token - is status 0, outcome unknown.
export async function call<T>(label: string, fn: () => Promise<{ result: T }>): Promise<T> {
  try {
    return (await fn()).result;
  } catch (e) {
    if (e instanceof ApiError) {
      const payload = (e.result ?? parse(e.body)) as { name?: string; details?: { issue?: string }[] } | undefined;
      const issue = payload?.details?.[0]?.issue ?? payload?.name ?? null;
      throw new PayPalError(`PayPal ${label} failed: ${issue ?? e.statusCode}`, e.statusCode, issue, header(e.headers, "paypal-debug-id"));
    }
    throw new PayPalError(`PayPal ${label} gave no answer`, 0, "NO_RESPONSE", null);
  }
}

function parse(body: unknown): unknown {
  if (typeof body !== "string" || !body) return undefined;
  try {
    return JSON.parse(body);
  } catch {
    return undefined;
  }
}

function header(headers: Record<string, string> | undefined, name: string): string | null {
  if (!headers) return null;
  const key = Object.keys(headers).find((k) => k.toLowerCase() === name);
  return key ? headers[key]! : null;
}

export const partnerMerchantId = () => env("PAYPAL_PARTNER_MERCHANT_ID");
